            if (period >= state.maxPeriods) { ds.finished = true; }
            var self = this;
            var nextP = (state.domainState && state.domainState.finished) ? state.currentPeriod : state.currentPeriod + 1;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state, nextP); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, k, g) {
            if (this.ROUND_OF[g] <= k) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _at(a, g, m) {
            return (m >= this.START[g]) ? a[g] : this.REF[g];
        }

        _demand(a, m, war) {
            var c = this.C;
            var pr = this.PRICE[this._at(a, 'precio1', m)];
            var p = pr[1];
            var sf = pr[2] * this.BUY[this._at(a, 'compras1', m)][3];
            var pavg = c.P0;
            if (war && m >= 10) {
                pavg = (c.RIVAL_CUT + 2 * c.P0) / 3.0;
                var r = this.RESP[this._at(a, 'resp4', m)];
                if (r[0] === 'match') {
                    p = Math.min(p, c.RIVAL_CUT);
                } else if (r[0] === 'under') {
                    p = Math.min(p, c.RIVAL_CUT) - c.UNDERCUT;
                }
                sf *= r[1];
            }
            var sh = Math.min(c.SHARE0 * Math.pow(p / pavg, -c.ELAST) * sf, c.SHARE_MAX);
            var mk = c.MKT * c.SEAS[m - 1] * ((war && m >= 10) ? c.Q4_DROP : 1.0);
            return [mk * sh, p, sh];
        }

        _event(dec, k) {
            var c = this.C;
            var a = {};
            var j, m;
            for (j = 0; j < this.KEYS.length; j++) { a[this.KEYS[j]] = this._active(dec, k, this.KEYS[j]); }
            var war = (k >= 4);
            var fc = [];
            for (m = 1; m <= 12; m++) { fc.push(this._demand(a, m, false)[0] * ((m >= 10) ? c.XMAS_FC : 1.0)); }
            fc.push(this._demand(a, 1, false)[0]);
            var stock = c.STOCK0, cash = c.CASH0, cmin = cash;
            var payQ = {};
            var ar = [c.AR0 / 2, c.AR0 / 2];
            var lost = 0.0, idle = 0.0, prof = 0.0, ebitda = 0.0, emerg = 0.0;
            var loan0 = c.LOAN0, newdebt = 0.0, line = 0.0, equityIn = 0.0;
            var IV = this.INV[a.inv3];
            var capex = IV[0], eff = IV[1], yrs = IV[2], mcap = IV[3], saving = IV[4];
            var fin = a.fin3;
            var matStock = 0.0;
            var matCost = this.BUY[a.compras1][0];
            if (a.compras1 === 'anual') {
                matStock = c.ANNUAL_QTY;
                payQ[1] = (payQ[1] || 0.0) + c.ANNUAL_QTY * this.BUY.anual[0];
            }
            var shareNum = 0.0, mktDen = 0.0, salesVal = 0.0, demTot = 0.0;
            for (m = 1; m <= 12; m++) {
                var dm = this._demand(a, m, war);
                var D = dm[0], p = dm[1];
                if (war && m === 12 && a.ajuste4 === 'outlet') { D *= c.OUTLET_DEMAND; }
                demTot += D;
                var st = this.STAFF[this._at(a, 'plant2', m)];
                var n = c.STAFF0 + st[0] + ((m >= 5 && m <= 9) ? st[1] : 0);
                var e = (m >= 7 && a.inv3 !== 'ninguna') ? eff : 1.0;
                var mc = (m >= 7) ? mcap : c.MACH;
                var regcap = n * c.UNITS * e;
                var ot = (m >= 5 && m <= 9) ? (c.STAFF0 * c.UNITS * e * st[2]) : 0.0;
                var cap = Math.min(regcap + ot, mc);
                var rule = (m >= 4) ? this._at(a, 'prod2', m) : 'prevision';
                var adj = war ? this._at(a, 'ajuste4', m) : 'mantener';
                var q;
                if (adj === 'ajustar') {
                    q = Math.max(D + 0.5 * this._demand(a, (m < 12) ? m + 1 : 1, war)[0] - stock, 0.0);
                } else if (adj === 'acelerar') {
                    q = cap;
                } else if (rule === 'prevision') {
                    q = Math.max(fc[m - 1] + 0.5 * fc[m] - stock, 0.0);
                } else if (rule === 'maxima') {
                    q = cap;
                } else if (rule === 'nivelada') {
                    if (m >= 4) {
                        var sf9 = 0.0, z;
                        for (z = 3; z < 12; z++) { sf9 += fc[z]; }
                        q = sf9 / 9.0;
                    } else {
                        q = cap;
                    }
                } else {
                    q = Math.max(c.FILL_MTO * D - stock, 0.0);
                }
                q = Math.min(q, cap);
                var bpol = this.BUY[this._at(a, 'compras1', m)];
                var matc;
                if (a.compras1 === 'anual') {
                    var useCheap = Math.min(q, matStock);
                    matStock -= useCheap;
                    var extra = q - useCheap;
                    matc = useCheap * this.BUY.anual[0] + extra * this.BUY.mensual[0];
                    payQ[m + 1] = (payQ[m + 1] || 0.0) + extra * this.BUY.mensual[0];
                } else {
                    matc = q * bpol[0];
                    var due = m + bpol[1];
                    if (fin === 'proveedores' && m >= 7) { due = m + 4; }
                    due = Math.max(due, m);
                    payQ[due] = (payQ[due] || 0.0) + matc;
                }
                var good = q * bpol[2];
                var avail = stock + good;
                var sold;
                if (rule === 'pedidos' && !(war && m >= 10 && (adj === 'ajustar' || adj === 'acelerar'))) {
                    sold = Math.min(c.FILL_MTO * D, avail);
                } else {
                    sold = Math.min(D, avail);
                }
                lost += D - sold;
                stock = avail - sold;
                idle += Math.max(regcap - q, 0.0);
                var r = (war && m >= 10) ? this.RESP[this._at(a, 'resp4', m)] : ['keep', 1.0, 0.0, 0.0];
                var revenue = sold * p;
                var outlet = 0.0, surplus = 0.0;
                if (war && m === 12 && a.ajuste4 === 'outlet') {
                    surplus = Math.max(stock - 0.5 * fc[12], 0.0);
                    outlet = surplus * c.OUTLET_P;
                    stock -= surplus;
                }
                var varc = q * (c.OTHERVAR - ((m >= 7) ? saving : 0.0)) + sold * c.LOGI + sold * r[2];
                var wages = ot ? (n * c.WAGE + (ot / c.UNITS / e) * c.WAGE * c.OT_PREM) : n * c.WAGE;
                var hold = stock * c.HOLD + Math.max(stock - c.WH, 0.0) * c.WH_X;
                if (a.compras1 === 'anual') { hold += matStock * this.BUY.anual[0] * c.ANNUAL_HOLD; }
                var oneoff = (war && m === 10) ? r[3] : 0.0;
                var dep = c.DEP0 + ((m >= 7) ? capex / yrs / 12.0 : 0.0);
                var intr = loan0 * c.LOAN0_R / 12.0 + newdebt * c.LOAN_R / 12.0 + line * c.LINE_R / 12.0;
                var op = revenue + outlet - matc - varc - wages - hold - c.OVER - oneoff;
                var invDelta = (good - sold) * (matCost + c.OTHERVAR);
                if (war && m === 12 && a.ajuste4 === 'outlet') { invDelta -= surplus * (matCost + c.OTHERVAR); }
                ebitda += op + invDelta;
                prof += op + invDelta - dep - intr;
                ar.push(revenue);
                var coll = ar[m - 1] + outlet;
                cash += coll - (payQ[m] || 0.0) - varc - wages - hold - c.OVER - oneoff - intr;
                cash -= c.LOAN0_P;
                loan0 -= c.LOAN0_P;
                if (m === 7 && capex > 0) {
                    cash -= capex;
                    if (fin === 'prestamo') {
                        newdebt += capex; cash += capex;
                    } else if (fin === 'ampliacion') {
                        equityIn += capex; cash += capex - c.AMP_COST; prof -= c.AMP_COST;
                    } else if (fin === 'poliza') {
                        line += capex; cash += capex;
                    }
                }
                if (fin === 'prestamo' && m >= 8 && newdebt > 0) {
                    var pp = capex / c.LOAN_N;
                    newdebt -= pp; cash -= pp;
                }
                if (cash < 0) {
                    var ee = -cash * c.EMERG / 12.0;
                    emerg += ee; prof -= ee; cash -= ee;
                }
                cmin = Math.min(cmin, cash);
                shareNum += sold;
                mktDen += c.MKT * c.SEAS[m - 1] * ((war && m >= 10) ? c.Q4_DROP : 1.0);
                salesVal += revenue + outlet;
            }
            var tax = (prof > 0) ? c.TAX * prof : 0.0;
            var net = prof - tax;
            var equity = c.EQ0 + equityIn;
            var roe = 100.0 * net / equity;
            var arEnd = ar[12] + ar[13];
            var payEnd = 0.0, kk;
            for (kk in payQ) {
                if (Object.prototype.hasOwnProperty.call(payQ, kk) && Number(kk) > 12) { payEnd += payQ[kk]; }
            }
            var od = (cash < 0) ? -cash : 0.0;
            var curLiab = payEnd + line + od + 12 * c.LOAN0_P + ((fin === 'prestamo') ? 12.0 * capex / c.LOAN_N : 0.0) + tax + c.OTHER_CL;
            var liq = (Math.max(cash, 0.0) + arEnd) / curLiab;
            var value = c.MULT * ebitda;
            var share = 100.0 * shareNum / mktDen;
            var coh = this._clamp(100.0 - 100.0 * (lost + Math.max(stock - 0.5 * fc[12], 0.0) + 0.25 * idle) / demTot, 0.0, 100.0);
            var hard = 0;
            for (j = 0; j < this.HARD.length; j++) {
                var gk = this.HARD[j][0];
                if (a[gk] === this.HARD[j][1] && k >= this.ROUND_OF[gk]) { hard += 1; }
            }
            return { k: k, a: a, sales: salesVal, prof: prof, net: net, roe: roe, liq: liq, value: value, share: share,
                     coh: coh, cash: cash, cmin: cmin, emerg: emerg, lost: lost, stock: stock, idle: idle, hard: hard };
        }

        _components(r) {
            var c = this.C;
            return [this._clamp((r.net - c.P_LO) / (c.P_HI - c.P_LO), 0, 1),
                    this._clamp((r.share - c.S_LO) / (c.S_HI - c.S_LO), 0, 1),
                    this._clamp((r.roe - c.R_LO) / (c.R_HI - c.R_LO), 0, 1),
                    this._clamp((r.liq - c.L_LO) / (c.L_HI - c.L_LO), 0, 1),
                    this._clamp((r.value - c.V_LO) / (c.V_HI - c.V_LO), 0, 1),
                    this._clamp((r.coh - c.CO_LO) / (c.CO_HI - c.CO_LO), 0, 1)];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._event(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_P, c.W_S, c.W_R, c.W_L, c.W_V, c.W_C];
            var tw = 0, num = 0, i;
            for (i = 0; i < 6; i++) { tw += w[i]; num += w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
            }
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.ROUND_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'es';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = (this._lang() === 'en') ? ',' : '.';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (n < 0 && v > 0 ? '-' : '') + out;
        }

        _fmtDec(n) {
            var v = Math.round(n * 10) / 10;
            var whole = Math.floor(Math.abs(v));
            var dec = Math.round((Math.abs(v) - whole) * 10);
            var s = String(whole) + ((this._lang() === 'en') ? '.' : ',') + String(dec);
            return (v < 0 ? '-' : '') + s;
        }

        _r1(x) {
            return this._jsround(x * 10.0) / 10.0;
        }

        _r2(x) {
            return this._jsround(x * 100.0) / 100.0;
        }

        _fmtDec2(n) {
            var v = this._r2(n);
            var neg = v < 0;
            var cents = Math.round(Math.abs(v) * 100);
            var whole = Math.floor(cents / 100);
            var dec = cents - whole * 100;
            var s = String(whole) + ((this._lang() === 'en') ? '.' : ',') + (dec < 10 ? '0' : '') + String(dec);
            return (neg && cents > 0 ? '-' : '') + s;
        }

        _fmtPct1(n) {
            return this._fmtDec(n) + ((this._lang() === 'en') ? '%' : ' %');
        }

        _fmtMoney(n) {
            var v = Math.round(n);
            var body = this._fmtInt(Math.abs(v));
            if (this._lang() === 'en') { return (v < 0 ? '-' : '') + '€' + body; }
            return (v < 0 ? '-' : '') + body + ' €';
        }

        _sum(arr) {
            var s = 0, i;
            for (i = 0; i < arr.length; i++) { s += arr[i]; }
            return s;
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(key) {
                var el = document.getElementById(key);
                if (el && k[key]) { el.value = k[key]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state, forcedPeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = forcedPeriod || state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var sH = ds.shareHistory || [];
            var pH = ds.profitHistory || [];
            var rH = ds.roeHistory || [];
            var lH = ds.liqHistory || [];
            var vH = ds.valueHistory || [];
            var cH = ds.cohHistory || [];
            var n = sH.length;
            this._set('shareDisplay', n ? this._fmtPct1(sH[n - 1]) : '-');
            this._set('profitDisplay', n ? this._fmtMoney(pH[n - 1]) : '-');
            this._set('roeDisplay', n ? this._fmtPct1(rH[n - 1]) : '-');
            this._set('liqDisplay', n ? this._fmtDec2(lH[n - 1]) : '-');
            this._set('valueDisplay', n ? this._fmtMoney(vH[n - 1]) : '-');
            this._set('cohDisplay', n ? this._fmtInt(cH[n - 1]) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        _fbKey(g, v) {
            var pfx = { precio1: 'pr', compras1: 'co', prod2: 'pd', plant2: 'pl', inv3: 'iv', fin3: 'fn', resp4: 'rs', ajuste4: 'aj' };
            var opts = {
                precio1: ['medio', 'bajo', 'alto', 'rappel'],
                compras1: ['contrato', 'mensual', 'anual', 'asia'],
                prod2: ['prevision', 'maxima', 'nivelada', 'pedidos'],
                plant2: ['fijos', 'discont', 'horas', 'nadie'],
                inv3: ['segunda', 'nueva', 'nave', 'ninguna'],
                fin3: ['prestamo', 'poliza', 'ampliacion', 'proveedores'],
                resp4: ['igualar', 'servicio', 'rebajar', 'publicidad'],
                ajuste4: ['ajustar', 'mantener', 'acelerar', 'outlet']
            };
            var keys = {
                fb_pr_medio: 1, fb_pr_bajo: 1, fb_pr_alto: 1, fb_pr_rappel: 1,
                fb_co_contrato: 1, fb_co_mensual: 1, fb_co_anual: 1, fb_co_asia: 1,
                fb_pd_prevision: 1, fb_pd_maxima: 1, fb_pd_nivelada: 1, fb_pd_pedidos: 1,
                fb_pl_fijos: 1, fb_pl_discont: 1, fb_pl_horas: 1, fb_pl_nadie: 1,
                fb_iv_segunda: 1, fb_iv_nueva: 1, fb_iv_nave: 1, fb_iv_ninguna: 1,
                fb_fn_prestamo: 1, fb_fn_poliza: 1, fb_fn_ampliacion: 1, fb_fn_proveedores: 1,
                fb_rs_igualar: 1, fb_rs_servicio: 1, fb_rs_rebajar: 1, fb_rs_publicidad: 1,
                fb_aj_ajustar: 1, fb_aj_mantener: 1, fb_aj_acelerar: 1, fb_aj_outlet: 1
            };
            if (!opts[g] || opts[g].indexOf(v) < 0) { return 'fb_next'; }
            var key = 'fb_' + pfx[g] + '_' + v;
            return keys[key] ? key : 'fb_next';
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var m = this._event(this._flat(state, p), p);
            var a = m.a;
            if (m.hard > 0) { return this._t('hint_cap'); }
            var ctl = this.CONTROLS[p] || [];
            var i;
            for (i = 0; i < ctl.length; i++) {
                if (a[ctl[i]] !== this.BEST[ctl[i]]) { return this._t(this._fbKey(ctl[i], a[ctl[i]])); }
            }
            return null;
        }

        getChartConfig() {
            return {
                profitChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Net profit', data: [], borderColor: '#8a4513', backgroundColor: 'rgba(138,69,19,0.12)', borderWidth: 2 }
                        ]
                    },
                    options: { responsive: true }
                },
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Round score', data: [], borderColor: '#8a4513', backgroundColor: 'rgba(138,69,19,0.35)', borderWidth: 1 },
                            { label: 'Coherence between departments', data: [], borderColor: '#2f6b3a', backgroundColor: 'rgba(47,107,58,0.30)', borderWidth: 1 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true, max: 100 } } }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var profitHistory = ds.profitHistory || [];
            var cohHistory = ds.cohHistory || [];
            var scoreHistory = ds.scoreHistory || [];
            var self = this;
            var labels = profitHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); });
            return {
                profitChart: {
                    labels: labels,
                    datasets: [
                        { data: profitHistory.slice(), label: this._t('chart_profit') }
                    ]
                },
                scoreChart: {
                    labels: scoreHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); }),
                    datasets: [
                        { data: scoreHistory.slice(), label: this._t('chart_score') },
                        { data: cohHistory.slice(), label: this._t('chart_coh') }
                    ]
                }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            var pct1 = function(v) { return self._fmtPct1(v); };
            var money = function(v) { return self._fmtMoney(v); };
            var intf = function(v) { return self._fmtInt(v); };
            var dec2 = function(v) { return self._fmtDec2(v); };
            return [
                { key: 'results.share', label: 'Share (%)', i18nKey: 'col_share', formatter: pct1 },
                { key: 'results.profit', label: 'Net profit', i18nKey: 'col_profit', formatter: money },
                { key: 'results.roe', label: 'ROE (%)', i18nKey: 'col_roe', formatter: pct1 },
                { key: 'results.liq', label: 'Acid-test ratio', i18nKey: 'col_liq', formatter: dec2 },
                { key: 'results.value', label: 'Firm value', i18nKey: 'col_value', formatter: money },
                { key: 'results.coh', label: 'Coherence', i18nKey: 'col_coh', formatter: intf },
                { key: 'results.roundScore', label: 'Round score', i18nKey: 'col_score' }
            ];
        }

        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var mm = Math.max(1, n);
            var d = this._flat(state, mm);
            var m = this._event(d, mm);
            var kp = this._kpis(m);
            var composite = this._composite(state);
            var insights = [];
            var self = this;
            var shown = this.KEYS.filter(function(g) { return self.ROUND_OF[g] <= mm; });
            shown.forEach(function(g) { insights.push(self._t(self._fbKey(g, self._active(d, mm, g)))); });
